  export Public provides Weave, Left, Right
  export Internal reveals Weave, Left, Right
  opaque function Weave(s: seq<int>, t: seq<int>): seq<int>
    decreases |s|
  {
    if |s| == 0 || |t| == 0 then []
    else [s[0],t[0]] + Weave(s[1..],t[1..])
  }
  opaque function Left(u: seq<int>): seq<int>
    decreases |u|
